positional:
var S=window.SugarCube, setup=S.setup, sv=S.State.variables;
try {
  sv.game_state = sv.game_state || {}; sv.game_state.quests = {}; sv.game_state.scheduled=[];
  sv.flags = sv.flags || {};
  // G4
  setup.applyQuestEffect('q1','start',null);
  var active = setup.isQuestActive('q1');
  setup.applyQuestEffect('q1','update',2);
  var condStep = setup.triggerConditionsSatisfied({version:'1.0',items:[{type:'quest',quest_id:'q1',operator:'step_gte',value:2}]});
  setup.applyQuestEffect('q1','complete',null);
  var done = setup.isQuestCompleted('q1');
  // G5 — schedule then fire directly (advanceDay needs full game init at Start)
  setup.scheduleEvent({delayDays:1, action:'set_flag', flag:'sched_test'});
  var schedLen = sv.game_state.scheduled.length;
  setup.fireScheduledEvent(sv.game_state.scheduled[0]);
  var fired = !!sv.flags.sched_test;
  // G2
  setup.phone_data.apps.push({id:'_smk', type:'social_feed', label:'X', post_actions:[{label:'Selfie',followers_min:5,followers_max:5,counter_trait:'followers'}]});
  sv.player.core_traits = sv.player.core_traits || {}; sv.player.core_traits.followers = 0;
  setup.sendSocialPost('_smk',0);
  var followers = sv.player.core_traits.followers;
  var blocked2nd; setup.sendSocialPost('_smk',0); blocked2nd = (sv.player.core_traits.followers === followers);
  return JSON.stringify({active:active, condStep:condStep, done:done, schedLen:schedLen, fired:fired, followers:followers, dailyCapBlocks2nd:blocked2nd});
} catch(e){ return JSON.stringify({error:String(e)}); }
